#!/usr/bin/env node
/** Concatenates the migrations and the menu seed into supabase/setup.sql (one paste in the SQL editor). */
import { readFileSync, writeFileSync } from 'node:fs';
const parts = ['supabase/migrations/0001_init.sql', 'supabase/migrations/0002_staff_dashboard.sql', 'supabase/seed.sql'];
const header = `-- =====================================================================================
-- Canvas O Coffee: COMPLETE DATABASE SETUP (generated by scripts/build-setup-sql.mjs)
-- Paste this whole file into Supabase → SQL Editor → New query, then press Run.
-- Safe to run again: it updates the menu and keeps existing orders and the sold-out switches.
-- =====================================================================================
`;
writeFileSync('supabase/setup.sql', header + parts.map((p) => `\n-- ----- ${p} -----\n` + readFileSync(p, 'utf8')).join('\n'));
console.log('[setup] supabase/setup.sql written');
